#include <iostream>
using namespace std;

// 函数原型声明：把函数头抄一遍，末尾加个分号。
// 定义写在 main 后面时，没有这一行，编译器读到 main 里的调用就不认识 digit_sum。
int digit_sum(int n);

int main() {
    int n;
    cin >> n;

    // 传进去的是 n 的一份拷贝，函数里怎么改都影响不到 main 里的 n
    cout << digit_sum(n) << endl;
    return 0;
}

// 函数定义：返回 n 的各位数字之和
int digit_sum(int n) {
    int sum = 0;
    // n 是形参，只在函数体里有效，相当于一个局部变量
    while (n > 0) {
        sum += n % 10;   // % 10 取出最后一位
        n /= 10;         // 整数除法丢掉最后一位
    }
    // n 为 0 时循环一次也不进，sum 保持 0 —— 正好是正确答案
    return sum;
}

