#include <iostream>
using namespace std;

// 默认参数写在声明里：不传 exp 时就按 2 算。
// 默认值只能出现一次 —— 这里声明写了 = 2，下面的定义就不要再写。
long long power(int base, int exp = 2);

int main() {
    int n;
    cin >> n;

    cout << power(n) << endl;      // 只给一个实参 → exp 用默认值 2
    cout << power(n, 3) << endl;   // 给了第二个实参 → 覆盖默认值
    return 0;
}

long long power(int base, int exp) {
    long long result = 1;
    for (int i = 0; i < exp; i++) {
        result *= base;
    }
    // exp 为 0 时循环一次都不进，result 保持 1
    return result;
}

tutorial.body:
默认参数和重载放在一起很容易踩坑。看这两个声明：

void print(int a);
void print(int a, int b = 0);

调用 print(5) 时，第一个版本正好匹配，第二个版本也能靠默认值匹配 —— 两条路都走得通，编译器不知道该选哪条，直接报二义性错误（错误信息里会出现 ambiguous）。

关键要记住：这种情况下编译器不会「随便挑一个先跑跑看」，而是当场拒绝编译。重载的挑选规则是「找唯一的最佳匹配」，一旦有两条同样可行的路，程序就是错的。

规律是：默认参数让「这个函数能接受几个实参」变得模糊，而重载恰恰是靠实参个数和类型来区分的，两者信息一重叠就会打架。所以写代码时的原则是——同一组功能不要既用重载又用默认参数去凑参数个数，要么全用重载，要么一个函数配默认参数。

tutorial.code:
// 一个函数配默认值就够了，不需要再写一个只收一个参数的版本
long long power(int base, int exp = 2);

power(5);      // 5 的平方
power(5, 3);   // 5 的立方

