#include <iostream>
#include <iomanip>
using namespace std;

// 三个同名函数靠参数列表区分，这就是函数重载。
// 注意：返回类型不参与区分，只有返回类型不同的两个同名函数是非法重载。
int maxOf(int a, int b);
int maxOf(int a, int b, int c);
double maxOf(double a, double b);

int main() {
    int a, b, c;
    double x, y;

    // cin 的 >> 会自动跳过空格和换行，所以分几行读都行
    cin >> a >> b;
    cin >> c;
    cin >> x >> y;

    // 实参是三个 int → 命中三参数的 int 版本
    cout << maxOf(a, b, c) << endl;

    // 实参是两个 double → 命中 double 版本。
    // 编译器是看实参类型挑版本，不会「看心情」乱选
    cout << fixed << setprecision(2) << maxOf(x, y) << endl;
    return 0;
}

int maxOf(int a, int b) {
    return a > b ? a : b;
}

int maxOf(int a, int b, int c) {
    // 重载之间可以互相调用，不必把两两比较的代码再抄一遍
    return maxOf(maxOf(a, b), c);
}

double maxOf(double a, double b) {
    return a > b ? a : b;
}

#include <iostream>
using namespace std;

void swap_value(int a, int b);
void swap_ref(int& a, int& b);

int main() {
    int a, b;
    cin >> a >> b;

    swap_value(a, b);
    // a、b 一点没变：函数里交换的是两份拷贝
    cout << "值传递后: " << a << " " << b << endl;

    swap_ref(a, b);
    // a、b 真的换了：形参就是它们的别名
    cout << "引用传递后: " << a << " " << b << endl;

    cout << "最终: " << a << " " << b << endl;
    return 0;
}

// 值传递：形参 a、b 是 main 里那两个变量的副本
void swap_value(int a, int b) {
    int t = a;
    a = b;
    b = t;
    // 这三步本身没错，麻烦在于换的是副本，函数一返回副本就没了
}

// 引用传递：形参 a、b 直接绑定到实参身上，就是同一个变量
void swap_ref(int& a, int& b) {
    int t = a;
    a = b;
    b = t;
}

tutorial.code:
void swap_value(int a, int b) {
    int t = a;
    a = b;
    b = t;
}

int x = 3, y = 8;
swap_value(x, y);
cout << x << " " << y << endl;   // 还是 3 8

void swap_ref(int& a, int& b) {
    int t = a;
    a = b;
    b = t;
}

int x = 3, y = 8;
swap_ref(x, y);
cout << x << " " << y << endl;   // 变成 8 3

