#include <iostream>
using namespace std;

long long factorial(int n);

int main() {
    int n;
    cin >> n;
    cout << factorial(n) << endl;
    return 0;
}

long long factorial(int n) {
    // 基准情形：递归的出口。0! 和 1! 都等于 1。
    // 少了这一句，函数会一直调用自己，直到把栈空间耗尽而崩溃（栈溢出）。
    if (n <= 1) {
        return 1;
    }

    // 递归情形：把大问题拆成小一号的同类问题。
    // n 是 int、factorial 返回 long long，相乘时 n 会自动转成 long long，不会溢出
    return n * factorial(n - 1);
}

tutorial.code:
long long factorial(int n) {
    if (n <= 1) {
        return 1;                 // 基准情形
    }
    return n * factorial(n - 1);  // 递推关系
}

// 13! 装不进 int，这里得到的不是正确答案
int bad = 1;
for (int i = 1; i <= 13; i++) {
    bad *= i;
}
cout << bad << endl;

// 换成 long long 就对了
long long good = 1;
for (int i = 1; i <= 13; i++) {
    good *= i;
}
cout << good << endl;

