#include <iostream>
using namespace std;

long long fib(int n);

int main() {
    int n;
    cin >> n;

    cout << fib(n) << endl;

    // 求和放在 main 里循环做：递归函数只负责「求第 n 项」这一件事
    long long sum = 0;
    for (int i = 1; i <= n; i++) {
        sum += fib(i);
    }
    cout << sum << endl;
    return 0;
}

long long fib(int n) {
    // 基准情形：前两项都是 1，到这里就不用再往下拆。
    // 必须用 n <= 2 一次挡住两种情况，只写 n == 1 的话
    // n = 2 时会去调用 fib(0)、fib(-1)，参数越跑越小，永远碰不到出口
    if (n <= 2) {
        return 1;
    }

    // 递归情形：照定义写 —— 每一项等于前两项之和
    return fib(n - 1) + fib(n - 2);
}

tutorial.code:
long long fib(int n) {
    if (n <= 2) {
        return 1;                      // 定义给出的起点
    }
    return fib(n - 1) + fib(n - 2);    // 定义给出的递推关系
}

// 递推写法：同样算 F(30)，只用了不到 30 次加法
long long a = 1, b = 1;
for (int i = 3; i <= 30; i++) {
    long long c = a + b;
    a = b;
    b = c;
}
cout << b << endl;   // F(30)
